import java.io.*;import java.util.*;import java.util.stream.*;import static java.util.stream.Collectors.toList;class Result {public static String larrysArray(List<Integer> A) {int inversions = 0;int n = A.size();for (int i = 0; i < n; i++) {for (int j = i + 1; j < n; j++) {if (A.get(i) > A.get(j)) {inversions++;}}}return (inversions % 2 == 0) ? "YES" : "NO";}}public class Solution {public static void main(String[] args) throws IOException {BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));BufferedWriter bufferedWriter = new BufferedWriter(new OutputStreamWriter(System.out));String line = bufferedReader.readLine();if (line != null) {int t = Integer.parseInt(line.trim());for (int i = 0; i < t; i++) {int n = Integer.parseInt(bufferedReader.readLine().trim());List<Integer> A = Stream.of(bufferedReader.readLine().split(" ")).map(Integer::parseInt).collect(toList());String result = Result.larrysArray(A);bufferedWriter.write(result);bufferedWriter.newLine();}}bufferedReader.close();bufferedWriter.close();}}